import React from 'react'
import { connect } from 'react-redux'
import { Row, Col, Button, Table, Alert, Spin } from 'antd'
import LayoutContent from '../../../components/utility/layoutContent'
import LayoutContentWrapper from '../../../components/utility/layoutWrapper'
import QueryString from 'query-string'
import NotificationActions from '../../redux/notifications/actions'
import moment from 'moment-timezone'

const { resetNotificationCore, getPublishedTemplate } = NotificationActions

class PublishedTemplateDetail extends React.Component {
    state = {
      loader: true,
      dataPublishedTemplate: {}
    }
    back = () => {
      const { history } = this.props
      history.push('/notifications')
    }
    componentWillReceiveProps (nextProps) {
      const { dataPublishedTemplate, getPublishTemplateStatus } = nextProps.Notifications
      if (getPublishTemplateStatus !== '') {
        this.setState({
          getPublishTemplateStatus,
          dataPublishedTemplate,
          loader: false
        })
      }
    }
    componentDidMount () {
      const querySearch = QueryString.parse(this.props.location.search)
      this.props.getPublishedTemplate(querySearch)
    }
    componentWillUnmount () {
      this.props.resetNotificationCore()
    }
    onCloseAlert = () => {
      this.props.resetNotificationCore()
      this.setState({ getPublishTemplateStatus: '' })
    }
    extractData =(data) => {
      const { profileData } = this.props
      return (
        <React.Fragment>
          {
            (data && data.length)
              ? <Col style={{ marginTop: 10 }}>
                <div style={{ border: '1px solid black', width: '100%', height: 'auto', padding: 10, margin: '5px 0px' }}>
                  {
                    data &&
                data.map((item) => {
                  return (
                    <div style={{ border: '1px solid black', width: '100%', height: 'auto', padding: 10, margin: '5px 0px' }}>
                      <Row>
                        <Col span={4}>
                          <b><p>Partner Code</p></b>
                        </Col>
                        <Col span={20}>
                          {item && item.partner_code}
                        </Col>
                      </Row>
                      <Row>
                        <Col span={4}>
                          <b><p>Product Key</p></b>
                        </Col>
                        <Col span={20}>
                          {item && item.product_key}
                        </Col>
                      </Row>
                      <Row>
                        <Col span={4}>
                          <b><p>TimeStamp</p></b>
                        </Col>
                        <Col span={20}>
                          {item && moment.utc(item.timestamp).tz(profileData && profileData.user_timezone).format('lll') }
                        </Col>
                      </Row>
                      <Row>
                        <Col>

                          <Row>
                            <Col span={4}>
                              <b><p> Trigger ID:</p></b>
                            </Col>
                            <Col span={20}>
                              {item.trigger && item.trigger['id']}
                            </Col>
                          </Row>
                          <Row>
                            <Col span={4}>
                              <b><p> Trigger Name:</p></b>
                            </Col>
                            <Col span={20}>
                              {item.trigger && item.trigger['name']}
                            </Col>
                          </Row>

                          <Row>
                            <Col span={4}>
                              <b><p>Trigger Type:</p></b>
                            </Col>
                            <Col span={20}>
                              {item.trigger && item.trigger['trigger_type']}
                            </Col>
                          </Row>

                        </Col>
                      </Row>
                    </div>
                  )
                })
                  }
                </div>
              </Col>
              : ''
          }

        </React.Fragment>
      )
    }
    render () {
      const { dataPublishedTemplate } = this.state
      const columns = [
        {
          dataIndex: 'name',
          width: 150
        }, {
          dataIndex: 'value'
        }
      ]
      let dataInfo = []
      let count = 0
      for (let key in dataPublishedTemplate) {
        let titleReplace = key.replace(/_/gi, ' ')
        let upperCase = titleReplace.charAt(0).toUpperCase() + titleReplace.substr(1)
        dataInfo = [...dataInfo, {
          key: count,
          name: <strong>{dataPublishedTemplate[key] !== undefined && upperCase}</strong>,
          value: dataPublishedTemplate[key] !== undefined ? (typeof (dataPublishedTemplate[key]) !== 'object' ? dataPublishedTemplate[key] : this.extractData(dataPublishedTemplate[key])) : ''
        }]
        count++
      }
      return (
        <LayoutContentWrapper>
          {
            (this.state.getPublishTemplateStatus !== '' && this.state.getPublishTemplateStatus !== undefined && this.state.getPublishTemplateStatus !== 'success') && (
              <Row style={{ width: '100%', marginBottom: '10px' }}>
                <Col>
                  <Alert
                    message={this.state.getPublishTemplateStatus}
                    type={'error'}
                    closable
                    onClose={this.onCloseAlert}
                  />
                </Col>
              </Row>
            )
          }
          <LayoutContent>
            <Row>
              <Col>
                <Button onClick={this.back}>Back</Button>
              </Col>
              <Col>
                <Spin spinning={this.state.loader}>
                  <Table
                    pagination={false}
                    showHeader={false}
                    columns={columns}
                    dataSource={dataInfo}
                  />
                </Spin>
              </Col>
            </Row>
          </LayoutContent>
        </LayoutContentWrapper>
      )
    }
}

export default connect(
  state => ({
    profileData: state.Auth.profile,
    Notifications: state.Notifications
  }),
  { getPublishedTemplate, resetNotificationCore }
)(PublishedTemplateDetail)
